CREATE TABLE IF NOT EXISTS server (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, host VARCHAR(255) NOT NULL, port INT NOT NULL, os VARCHAR(50), status VARCHAR(20) NOT NULL, description VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS server_metric (id BIGINT AUTO_INCREMENT PRIMARY KEY, server_id BIGINT NOT NULL, cpu_usage DOUBLE NOT NULL, memory_usage DOUBLE NOT NULL, disk_usage DOUBLE NOT NULL, network_in DOUBLE, network_out DOUBLE, load_average DOUBLE, status VARCHAR(20) NOT NULL, collected_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_metric_server FOREIGN KEY (server_id) REFERENCES server(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS inspector_event (id VARCHAR(32) PRIMARY KEY, task_id VARCHAR(128) NOT NULL, target VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, severity VARCHAR(32) NOT NULL, category VARCHAR(64), agent_claim TEXT, reason TEXT NOT NULL, recommendation TEXT, requires_human BOOLEAN NOT NULL DEFAULT FALSE, metadata_json TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inspector_issue (id BIGINT AUTO_INCREMENT PRIMARY KEY, event_id VARCHAR(32) NOT NULL, category VARCHAR(64) NOT NULL, severity VARCHAR(32) NOT NULL, reason TEXT NOT NULL, recommendation TEXT, CONSTRAINT fk_inspector_issue_event FOREIGN KEY (event_id) REFERENCES inspector_event(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS inspection_evidence (id BIGINT AUTO_INCREMENT PRIMARY KEY, event_id VARCHAR(32) NOT NULL, content TEXT NOT NULL, source VARCHAR(500), version VARCHAR(100), score DOUBLE, CONSTRAINT fk_inspection_evidence_event FOREIGN KEY (event_id) REFERENCES inspector_event(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS inspection_verification (id BIGINT AUTO_INCREMENT PRIMARY KEY, event_id VARCHAR(32) NOT NULL, resolved BOOLEAN, status VARCHAR(100), details_json TEXT, verified_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_inspection_verification_event FOREIGN KEY (event_id) REFERENCES inspector_event(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS model_connections (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, provider VARCHAR(80) NOT NULL, base_url VARCHAR(500) NOT NULL, model_name VARCHAR(200) NOT NULL, api_key_ciphertext TEXT NOT NULL, api_key_last4 VARCHAR(4), enabled BOOLEAN NOT NULL DEFAULT TRUE, timeout_seconds INT NOT NULL DEFAULT 60, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_model_connections_user (user_id));
CREATE TABLE IF NOT EXISTS operation_session_group (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, parent_id BIGINT NULL, name VARCHAR(120) NOT NULL, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_operation_group_parent FOREIGN KEY (parent_id) REFERENCES operation_session_group(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS operation_credential (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, type VARCHAR(32) NOT NULL, secret_ciphertext TEXT NOT NULL, last4 VARCHAR(4), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_operation_credential_user (user_id));
CREATE TABLE IF NOT EXISTS operation_session (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, group_id BIGINT NULL, name VARCHAR(120) NOT NULL, protocol VARCHAR(32) NOT NULL, host VARCHAR(255) NOT NULL, port INT NOT NULL, username VARCHAR(255) NOT NULL, credential_id BIGINT NULL, identity_path VARCHAR(2048), jump_session_id BIGINT NULL, working_directory VARCHAR(2048), tags_json TEXT, description TEXT, accent VARCHAR(32), favorite BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(32) NOT NULL DEFAULT 'IDLE', last_connected_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_operation_session_group FOREIGN KEY (group_id) REFERENCES operation_session_group(id) ON DELETE SET NULL, CONSTRAINT fk_operation_session_credential FOREIGN KEY (credential_id) REFERENCES operation_credential(id) ON DELETE SET NULL, CONSTRAINT fk_operation_session_jump FOREIGN KEY (jump_session_id) REFERENCES operation_session(id) ON DELETE SET NULL, INDEX idx_operation_session_user (user_id));
CREATE TABLE IF NOT EXISTS operation_known_host (id BIGINT AUTO_INCREMENT PRIMARY KEY, session_id BIGINT NOT NULL, host VARCHAR(255) NOT NULL, port INT NOT NULL, algorithm VARCHAR(64) NOT NULL, fingerprint VARCHAR(255) NOT NULL, public_key TEXT NOT NULL, trusted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_operation_known_host_session FOREIGN KEY (session_id) REFERENCES operation_session(id) ON DELETE CASCADE, UNIQUE KEY uq_operation_known_host (session_id, host, port));
CREATE TABLE IF NOT EXISTS operation_tunnel (id BIGINT AUTO_INCREMENT PRIMARY KEY, session_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, type VARCHAR(32) NOT NULL, listen_address VARCHAR(255) NOT NULL, listen_port INT NOT NULL, target_host VARCHAR(255), target_port INT, status VARCHAR(32) NOT NULL DEFAULT 'STOPPED', last_error TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_operation_tunnel_session FOREIGN KEY (session_id) REFERENCES operation_session(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS operation_transfer (id BIGINT AUTO_INCREMENT PRIMARY KEY, session_id BIGINT NOT NULL, direction VARCHAR(32) NOT NULL, source_path TEXT NOT NULL, target_path TEXT NOT NULL, size_bytes BIGINT NOT NULL DEFAULT 0, transferred_bytes BIGINT NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL, error_message TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_operation_transfer_session FOREIGN KEY (session_id) REFERENCES operation_session(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS operation_command (id BIGINT AUTO_INCREMENT PRIMARY KEY, session_id BIGINT NULL, runtime_id VARCHAR(128), command_text TEXT NOT NULL, origin VARCHAR(32) NOT NULL, risk VARCHAR(32) NOT NULL, approval_state VARCHAR(32) NOT NULL, exit_status INT NULL, output_redacted BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_operation_command_session FOREIGN KEY (session_id) REFERENCES operation_session(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS operation_audit_event (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, session_id BIGINT NULL, command_id BIGINT NULL, action VARCHAR(64) NOT NULL, approval_state VARCHAR(32) NOT NULL, result VARCHAR(32), details_json TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_operation_audit_session FOREIGN KEY (session_id) REFERENCES operation_session(id) ON DELETE SET NULL, CONSTRAINT fk_operation_audit_command FOREIGN KEY (command_id) REFERENCES operation_command(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS operation_workspace (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, tabs_json TEXT NOT NULL, panes_json TEXT NOT NULL, active_pane VARCHAR(128), updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_operation_workspace_user (user_id));
CREATE TABLE IF NOT EXISTS operation_run_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, trace_id VARCHAR(64) NOT NULL, user_id BIGINT NOT NULL, session_id BIGINT NULL, runtime_id VARCHAR(128) NOT NULL, tool_id VARCHAR(128) NOT NULL, status VARCHAR(32) NOT NULL, started_at TIMESTAMP NOT NULL, ended_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_operation_run_trace (trace_id), INDEX idx_operation_run_user_time (user_id, started_at), INDEX idx_operation_run_tool_status (tool_id, status));
CREATE TABLE IF NOT EXISTS operation_run_output (id BIGINT AUTO_INCREMENT PRIMARY KEY, run_id BIGINT NOT NULL, sequence_no INT NOT NULL, command_text TEXT NOT NULL, exit_code INT NOT NULL, stdout_text LONGTEXT, stderr_text LONGTEXT, started_at TIMESTAMP NOT NULL, ended_at TIMESTAMP NOT NULL, CONSTRAINT fk_operation_run_output_record FOREIGN KEY (run_id) REFERENCES operation_run_record(id) ON DELETE CASCADE, UNIQUE KEY uq_operation_run_output_sequence (run_id, sequence_no));
CREATE TABLE IF NOT EXISTS operation_run_evidence (id BIGINT AUTO_INCREMENT PRIMARY KEY, run_id BIGINT NOT NULL, evidence_type VARCHAR(64) NOT NULL, content TEXT NOT NULL, source_ref VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_operation_run_evidence_record FOREIGN KEY (run_id) REFERENCES operation_run_record(id) ON DELETE CASCADE, INDEX idx_operation_run_evidence_type (evidence_type));
CREATE TABLE IF NOT EXISTS knowledge_candidate (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, source_type VARCHAR(32) NOT NULL, source_run_id BIGINT NOT NULL, trace_id VARCHAR(64) NOT NULL, tool_id VARCHAR(128) NOT NULL, title VARCHAR(255) NOT NULL, summary TEXT NOT NULL, content_markdown LONGTEXT NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'PENDING_REVIEW', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_knowledge_candidate_run (user_id, source_run_id), INDEX idx_knowledge_candidate_user_status (user_id, status, created_at), CONSTRAINT fk_knowledge_candidate_run FOREIGN KEY (source_run_id) REFERENCES operation_run_record(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS app_user (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(64) NOT NULL UNIQUE,
    password_hash VARCHAR(100) NOT NULL,
    role VARCHAR(16) NOT NULL,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
